b.concept('requirement_wrappers','GTL requirement declaration wrappers','Human-agent authoring declarations for requirement identity/relations/spans/staged context/destination topology/proof-evidence/evidence policy within GTL, without a second requirements language.',[(15,12,19)])
b.constraint('structural_language_laws',['gtl_law'],'All workflow structure is graph, with typed nodes carrying local meaning. Composition/substitution require aligned interfaces; work and convergence remain distinct. Associativity preserves outer contract, identity preserves interface, interface-equivalent functions interchange, refinement may alter only internals, recursion preserves explainable lineage and declared rebinding, and fan-out/fan-in/gate/promote preserve type/interface truth.',[(0,16,34)])
b.constraint('language_authority_laws',['gtl_law'],'GTL exposes lawful structure/candidates/hooks without hidden selection and supports event-sourced interpretation independently of a single engine. First-class opaque identities, not labels, target declarations. GTL declares Jobs over published functions/Roles; engines realize Runs, Workers, materialization, traversal and runtime truth. Hooks/config govern without tactic prescription or policy DSL. Boundaries may visibly declare invariant traversal, and publication/materialization/hooks/derived bundles stay inspectable and replayable.',[(0,36,50)])
b.constraint('diagnostic_identity_law',['conformance_diagnostic'],'Every conformance diagnostic uses stable identity from closed GTL_PROGRAM_DIAGNOSTIC_ID_VALUES and GtlProgramDiagnosticId located by abg.contract.abg.m03, or an identity whose namespace is admitted from declared policy rows. Unknown identity fails closed at construction. Declaration-carried identities are validated against admitted declarations as successor law. Release-stable identities may be removed only by supersession, never renamed.',[(0,52,60)],exceptions=['Declared policy rows may admit the namespace of a declaration-carried diagnostic identity.'])
b.constraint('typed_repair_affordances',['conformance_diagnostic'],'A ratified diagnostic may carry typed lawful repair moves naming repair surface, smallest lawful edit class and constitutional governing change class. Such carriers express declared truth, not prose advice, and never perform/select/authorize repair.',[(0,62,62)])
b.constraint('canonical_data_construction',['canonical_declaration'],'Use one stable canonical ordering/spelling and digest; alternatives are not rival truth. Native constructors may use total deterministic host computation on explicit typed inputs only if canonical serialization, lossless raw-admission roundtrip and same digest are witnessed. They are syntax, not declaration authority. Reject ambient process state, runtime events, filesystem discovery, randomness, clock time, unstable iteration, hidden defaults or Module export without exact roundtrip witness at the declaration boundary.',[(0,64,76)],conditions=['Native construction must be total, deterministic, explicit-input and canonically roundtrippable.'])
b.latitude('declared_data_latitude',['canonical_declaration'],['Bind ratified examples/counterexamples as content-digested admitted data through existing evidence-shape/counterexample-reference families for calibration and non-tautology mutation.','Explicitly mark deliberate underdetermination with owning F_P latitude or F_H decision route; invention is allowed only within that latitude.','Carry admitted author/authority factory provenance, with authorship checks governed by successor law.'],['Using golden data as closure authority.','Treating an undeclared hole as permission.','Letting authorship drive traversal; it joins runtime lineage by reference only.'],[(0,78,82)])
b.constraint('evolution_by_supersession',['canonical_declaration','conformance_diagnostic'],'Requirement relations include supersession. Contract/declaration evolution uses that existing relation-kind family without a second vocabulary; ratified identities can be removed only by supersession.',[(0,84,84)])
b.constraint('conformance_corpus_publication',['conformance_corpus'],'Publish exact corpus schema, asset, digest and diagnostic-vocabulary dependency through the Product public catalog. Every conforming toolchain replays every corpus entry to the exact expected diagnostic identities. Test-only fixtures are not publication; corpus is separate from requirement corpus and qualification evidence.',[(0,86,93)])
b.constraint('version_subject_binding',['constitutional_witness'],'Version subjects are a closed tagged family: mutable source project, immutable published RC cut, tapped release cut, released Product and stamped installed Product, never interchangeable. For every versioned surface resolve exactly one binding by binding ref and surface ref, then exactly one fact for its exact tagged subject before comparison. Missing, duplicate or kind-incoherent basis is version-basis-unresolved; disagreement with resolved same-subject fact is version-line-drift. Path, surface, version text and inferred latest cut cannot select/fabricate basis.',[(0,95,108)])
b.constraint('independent_drift_checks',['constitutional_witness','conformance_diagnostic'],'Assess live active-ticket references and public-seam keys against engine passthrough authority even if version basis fails. A release-bearing surface citing an active ticket yields release-claim-cites-active-ticket; missing witness digest yields surface-digest-missing; seam-key divergence yields seam-parity-drift. Every drift diagnostic carries ratified identity and an admissible existing-vocabulary repair. Detection belongs inside GTL validator, never a second checker or prose checklist.',[(0,109,117)])
b.constraint('uniform_retry_failure_law',['gtl_law'],'One RETRYABLE_RUNTIME_FAILURE_CLASS_VALUES allowlist judges uniform C-call spine outcomes under CCALL-009; no per-arm detours. Evaluator and composed-arm failures route identically to transform-arm failures.',[(1,121,125)])
b.constraint('module_publication_conservation',['module'],'Published GraphFunctions, refinements, candidate families, Jobs and Roles remain inspectable to importers, never anonymous realized surfaces. Module metadata is immutable and visible to consumers, policy and replay.',[(4,22,24)])
b.latitude('module_defaults',['module'],['Publish as reusable GTL workflow libraries.','Declare visible Module policy-hook defaults for imported callables, Jobs, Roles and runtime policy resolution.'],['Overriding more-specific hook truth unless the hook family explicitly declares that precedence.'],[(4,18,18),(4,26,26)])
b.constraint('node_markov_meaning',['node'],'Markov conditions declare local state/outcome/acceptance. Source conditions are upstream guarantees available downstream; target conditions are intended lawful-transformation obligations. Unspecified Markov defaults to empty tuple and declares no conditions.',[(7,19,23),(7,31,31)])
b.constraint('node_language_runtime_split',['node'],'Markov and AssetSurface are GTL declaration truth. TypeScript/validator may validate; HoG traverses/resolves admitted binding; ABG admits observations and projects runtime facts but cannot own, interpret or invent the declaration or missing asset law. Every interpretation/serialization/bridge preserves schema, Markov and AssetSurface contract without semantic loss.',[(7,25,35),(7,39,44)])
b.latitude('node_contract_variation',['node'],['Use concrete type refs or symbolic schemas, including Vector[T].','Declare asset_surface for kind/schema role, required carried Contexts and standards/output-contract references.','Optionally bind a reusable node type by explicit compiler-visible reference; absence means exactly the inline schema/Markov/asset contract.'],['Deriving node-type meaning only from schema spelling, tags, prompts, filenames or downstream convention.'],[(7,33,37),(7,48,59)])
b.constraint('node_asset_interface_owner',['node'],'Renderer-backed, prompt-like or otherwise policy-rich assets use the detailed ASSET-SURFACE requirement. Node stays typed locus; asset interface stays subordinate declaration.',[(7,46,46)],conditions=['Node declares a policy-rich/renderer/prompt asset interface.'])
b.constraint('optional_type_strengthening',['node'],'When a type reference is present, construction/admission/serialization/conformance/bridges preserve it without loss. Satisfaction requires inline schema, Markov and AssetSurface to preserve or strengthen the referenced type; unknown reference or weakened declaration fails closed. Type reference is strengthening, not a mandatory admission field.',[(7,52,64)])
